 for path in ['units/classification','units/unit_quality','units/anno_name','intervals/trials/outcome','intervals/trials/early_lick','intervals/trials/trial_instruction','intervals/trials/task']:
  a=f[path][:]
  vals,c=np.unique(a,return_counts=True)
  print('\n',path,[(x.decode() if isinstance(x,bytes) else x,int(n)) for x,n in zip(vals,c)])
 for path in ['acquisition/BehavioralTimeSeries/Camera0_side_TongueTracking/data','acquisition/BehavioralTimeSeries/Camera0_side_TongueTracking/timestamps','acquisition/BehavioralEvents/go_start_times/timestamps','acquisition/BehavioralEvents/photostim_start_times/timestamps']:
